import incrnanmmeanvar from './index';


// TESTS //

// The function returns an accumulator function...
{
	incrnanmmeanvar(3); // $ExpectType accumulator
	const out = [0.0, 0.0];
	incrnanmmeanvar(out, 3); // $ExpectType accumulator
}

// The compiler throws an error if the function is provided a last argument that is not a number...
{
	// @ts-expect-error
	incrnanmmeanvar('5');
	// @ts-expect-error
	incrnanmmeanvar(true);
	// @ts-expect-error
	incrnanmmeanvar(false);
	// @ts-expect-error
	incrnanmmeanvar(null);
	// @ts-expect-error
	incrnanmmeanvar({});
	// @ts-expect-error
	incrnanmmeanvar((x: number): number => x);

	const out = [0.0, 0.0];
	// @ts-expect-error
	incrnanmmeanvar(out, '5');
	// @ts-expect-error
	incrnanmmeanvar(out, true);
	// @ts-expect-error
	incrnanmmeanvar(out, false);
	// @ts-expect-error
	incrnanmmeanvar(out, null);
	// @ts-expect-error
	incrnanmmeanvar(out, {});
	// @ts-expect-error
	incrnanmmeanvar(out, (x: number): number => x);
}

// The compiler throws an error if the function is provided an output array that is not an array-like object of numbers...
{
	// @ts-expect-error
	incrnanmmeanvar('5', 3);
	// @ts-expect-error
	incrnanmmeanvar(true, 3);
	// @ts-expect-error
	incrnanmmeanvar(false, 3);
	// @ts-expect-error
	incrnanmmeanvar(null, 3);
	// @ts-expect-error
	incrnanmmeanvar({}, 3);
	// @ts-expect-error
	incrnanmmeanvar((x: number): number => x, 3);
}

// The function returns an accumulator function which returns an accumulated result...
{
	const acc = incrnanmmeanvar(3);

	acc(); // $ExpectType ArrayLike<number> | null
	acc(3.14); // $ExpectType ArrayLike<number> | null
}

// The compiler throws an error if the returned accumulator function is provided invalid arguments...
{
	const acc = incrnanmmeanvar(3);

	// @ts-expect-error
	acc('5');
	// @ts-expect-error
	acc(true);
	// @ts-expect-error
	acc(false);
	// @ts-expect-error
	acc(null);
	// @ts-expect-error
	acc([]);
	// @ts-expect-error
	acc({});
	// @ts-expect-error
	acc((x: number): number => x);
}
